#include <stdio.h>
#include <stdlib.h>
#include <string.h>
struct Contact { char name[32]; int id; };
int by_name(const void *a, const void *b) {
 const struct Contact *x = a, *y = b;
 return strcmp(x->name, y->name);
}
int main(void) {
 struct Contact c[] = {{"Mira",2},{"Asha",1}};
 qsort(c, 2, sizeof c[0], by_name);
 puts(c[0].name);
 return 0;
}
